'use client';

import { FormEvent, useEffect, useState } from 'react';

type Course = { id: string; slug: string; title: string; description: string; category: string; level: string };
type Dashboard = { completedLessons: number; xp: number; certificates: unknown[]; enrollments: unknown[] };

const api = process.env.NEXT_PUBLIC_API_URL || '/api/v1';

export default function Home() {
  const [courses, setCourses] = useState<Course[]>([]);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [message, setMessage] = useState('');
  const [dashboard, setDashboard] = useState<Dashboard | null>(null);

  useEffect(() => {
    fetch(`${api}/courses`, { credentials: 'include' }).then((response) => response.ok ? response.json() : []).then(setCourses).catch(() => setCourses([]));
  }, []);

  async function login(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const response = await fetch(`${api}/auth/login`, { method: 'POST', credentials: 'include', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ email, password }) });
    if (!response.ok) return setMessage('Unable to sign in.');
    const session = await response.json() as { accessToken: string };
    sessionStorage.setItem('afghan-it.access-token', session.accessToken);
    const summary = await fetch(`${api}/dashboard`, { headers: { authorization: `Bearer ${session.accessToken}` }, credentials: 'include' });
    if (summary.ok) setDashboard(await summary.json());
    setMessage('Signed in. Your learning dashboard is ready.');
  }

  return <main>
    <header className="masthead"><div className="brand">Afghan <span>IT Academy</span></div><a href="#login">Sign in</a></header>
    <section className="hero"><div className="eyebrow">Built for practical progress</div><h1>Learn the work that moves your future.</h1><p>IT and English programmes with real projects, assessments, AI mentoring and verifiable certificates.</p></section>
    <section aria-labelledby="courses"><div className="section-title"><h2 id="courses">Explore programmes</h2><span>{courses.length} available</span></div><div className="course-grid">{courses.map((course) => <article className="course" key={course.id}><small>{course.category} · {course.level}</small><h3>{course.title}</h3><p>{course.description}</p></article>)}</div></section>
    <section className="login" id="login" aria-labelledby="login-title"><div className="section-title"><h2 id="login-title">Continue learning</h2></div><form onSubmit={login}><label>Email<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} required /></label><label>Password<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} required /></label><button>Sign in</button></form><p className="notice" role="status">{message}</p></section>
    {dashboard && <section className="dashboard" aria-labelledby="dashboard-title"><div className="section-title"><h2 id="dashboard-title">Your learning dashboard</h2></div><div className="stats"><div className="stat"><strong>{dashboard.enrollments.length}</strong>active courses</div><div className="stat"><strong>{dashboard.completedLessons}</strong>lessons completed</div><div className="stat"><strong>{dashboard.xp}</strong>XP earned</div></div></section>}
  </main>;
}
